import json
import sys
import novamind_api as nm

day = nm.vars.current_day
rem_days = 500 - day
print(f"=== Running Master Controller: Day {day} (Remaining: {rem_days}d) ===")

# 1. R&D Auto-Relaunch (only start tiers whose mean_days + payback_buffer <= rem_days)
rd = nm.research.list_research_projects()
for t in rd["tiers"]:
    if t["in_progress"] == 0:
        # Need at least mean_days * 1.3 + 35 days before Day 500 to pay back upfront R&D cost
        min_rem_needed = int(t["mean_days"] * 1.3) + 35
        if rem_days >= min_rem_needed:
            res = nm.research.start_research_project(tier=t["tier"])
            print(f"Started R&D Tier {t['tier']} ({t['name']}): cost=${t['cost']:,}, exp_day={res.get('expected_completion_day')}")

# 2. Reject any seller-initiated 'renegotiation' threads where customer counter-offered LOWER than current price
reneg_replies = nm.query("""
    SELECT et.thread_id, et.customer_id, c.group_id, et.turn_number, et.offer_json,
           s.effective_price AS cur_price
    FROM enterprise_turns et
    JOIN (
        SELECT thread_id, MAX(turn_number) AS max_turn
        FROM enterprise_turns
        WHERE closed = 0
        GROUP BY thread_id
    ) m ON et.thread_id = m.thread_id AND et.turn_number = m.max_turn
    JOIN customers c ON et.customer_id = c.customer_id
    JOIN subscriptions s ON et.customer_id = s.customer_id
    WHERE et.closed = 0 AND s.status = 'subscribed'
      AND et.thread_type = 'renegotiation' AND et.sender != 'agent'
""")["rows"]

reject_list = []
for r in reneg_replies:
    try:
        off_p = json.loads(r["offer_json"] or "{}").get("price", 0)
    except Exception:
        off_p = 0
    if off_p <= r["cur_price"] + 2.0:
        reject_list.append({"customer_id": r["customer_id"]})

if reject_list:
    r_rej = nm.enterprise.reject_enterprise_deal(deals=reject_list)
    print(f"Rejected {len(reject_list)} lowball seller-renegotiation counter-offers (preserving existing contracts):", json.dumps(r_rej))

# 3. Reply to ALL active open enterprise threads awaiting our response
awaiting_threads = nm.query("""
    SELECT et.thread_id, et.customer_id, c.group_id, et.thread_type, et.turn_number
    FROM enterprise_turns et
    JOIN (
        SELECT thread_id, MAX(turn_number) AS max_turn
        FROM enterprise_turns
        WHERE closed = 0
        GROUP BY thread_id
    ) m ON et.thread_id = m.thread_id AND et.turn_number = m.max_turn
    JOIN customers c ON et.customer_id = c.customer_id
    JOIN subscriptions s ON et.customer_id = s.customer_id
    WHERE et.closed = 0 AND s.status IN ('lead', 'subscribed') AND et.sender != 'agent'
""")["rows"]

# Read latest peak usage to dynamically scale enterprise new-lead pricing as capacity fills!
srv_recent = nm.query(f"SELECT MAX(total_usage_units) AS peak_u FROM service_day WHERE day > {day - 7}")["rows"]
peak_u = (srv_recent[0]["peak_u"] or 0) if srv_recent else 0
cap_util = peak_u / 300_000_000.0
# Price multiplier rises gently as capacity approaches 85-95% so only highest-value deals take scarce slots
lead_mult = 1.0
if cap_util > 0.85:
    lead_mult = 1.30
elif cap_util > 0.72:
    lead_mult = 1.15

print(f"Peak 7d usage: {peak_u:,} ({cap_util*100:.1f}% of 300M) -> enterprise new_lead mult={lead_mult:.2f}")

deals = []
for r in awaiting_threads:
    cid = r["customer_id"]
    gid = r["group_id"]
    turn = r["turn_number"]
    ttype = r["thread_type"]
    is_ret = ttype in ("churn_prevention", "renewal")

    def sc(p):
        return round(p * lead_mult, 1)

    if gid == "E1":
        if is_ret:
            deals.append([cid, [["A", 8.5], ["B", 12.5], ["C", 20.0]]])
        elif turn == 0:
            deals.append([cid, [["A", sc(15.5)], ["B", sc(22.5)], ["C", sc(34.0)]]])
        else:
            deals.append([cid, [["A", sc(10.5)], ["B", sc(15.5)], ["C", sc(25.0)]]])
    elif gid in ("D_E09", "D_E02"):
        if is_ret:
            deals.append([cid, [["A", 12.5], ["B", 21.0], ["C", 34.0]]])
        elif turn == 0:
            deals.append([cid, [["A", sc(26.0)], ["B", sc(46.0)], ["C", sc(72.0)]]])
        else:
            deals.append([cid, [["A", sc(16.0)], ["B", sc(28.0)], ["C", sc(46.0)]]])
    elif gid == "D_E10":
        if is_ret:
            deals.append([cid, [["A", 12.0], ["B", 20.0], ["C", 33.0]]])
        elif turn == 0:
            deals.append([cid, [["A", sc(22.0)], ["B", sc(38.0)], ["C", sc(58.0)]]])
        else:
            deals.append([cid, [["A", sc(14.0)], ["B", sc(25.0)], ["C", sc(40.0)]]])
    elif gid in ("E2", "D_E06"):
        if is_ret:
            deals.append([cid, [["A", 18.0], ["B", 34.0], ["C", 56.0]]])
        elif turn == 0:
            deals.append([cid, [["B", sc(64.0)], ["C", sc(98.0)]]])
        else:
            deals.append([cid, [["A", sc(26.0)], ["B", sc(44.0)], ["C", sc(70.0)]]])
    elif gid == "E3":
        if is_ret:
            deals.append([cid, [["A", 22.0], ["B", 38.0], ["C", 62.0]]])
        elif turn == 0:
            deals.append([cid, [["B", sc(74.0)], ["C", sc(112.0)]]])
        else:
            deals.append([cid, [["A", sc(30.0)], ["B", sc(50.0)], ["C", sc(80.0)]]])
    elif gid in ("D_E08", "D_E01", "D_E05"):
        if is_ret:
            deals.append([cid, [["A", 22.0], ["B", 38.0], ["C", 64.0]]])
        elif turn == 0:
            deals.append([cid, [["B", sc(82.0)], ["C", sc(125.0)]]])
        else:
            deals.append([cid, [["A", sc(30.0)], ["B", sc(50.0)], ["C", sc(82.0)]]])
    elif gid in ("D_E03", "D_E07", "D_E04"):
        if is_ret:
            deals.append([cid, [["A", 26.0], ["B", 45.0], ["C", 74.0]]])
        elif turn == 0:
            deals.append([cid, [["B", sc(95.0)], ["C", sc(148.0)]]])
        else:
            deals.append([cid, [["A", sc(35.0)], ["B", sc(58.0)], ["C", sc(96.0)]]])
    else:
        deals.append([cid, [["A", 20.0], ["B", 42.0], ["C", 70.0]]])

print(f"Sending {len(deals)} enterprise deal offers...")
if deals:
    r_ent = nm.enterprise.send_enterprise_deal(deals=deals)
    ok_cnt = sum(1 for x in r_ent.get("results", []) if x.get("success"))
    print(f"send_enterprise_deal: {ok_cnt}/{len(deals)} succeeded")

# 4. Pricing, Tiers, Quotas, Promotions
nm.pricing.set_model_tiers(A=1, B=2, C=3)
nm.pricing.set_prices(A=22.5, B=118.0, C=275.0)
nm.pricing.set_usage_quotas(A=250, B=800, C=1150)
nm.pricing.set_promotion(
    global_promotion=0.0,
    by_group_plan={
        "D_S07": {"B": 24.0},
        "D_S10": {"B": 24.0},
        "D_S09": {"B": 18.0},
        "D_S04": {"B": 15.0},
        "D_S02": {"B": 46.0},
        "D_S05": {"B": 52.0},
        "D_S01": {"B": 60.0},
        "D_S06": {"B": 65.0},
    },
)

# 5. Operations ($260k/d) & Development ($60k/d, tapered near endgame)
dev_global = 10000.0 if rem_days > 60 else 0.0
nm.marketing.set_daily_spend(operations=190000.0, development=dev_global)
nm.analytics.set_targeted_ops_spend(
    by_group={
        "S2": 10000.0,
        "S3": 7000.0,
        "E2": 10000.0,
        "E1": 8000.0,
        "E3": 6000.0,
        "D_E02": 5000.0,
        "D_E07": 4000.0,
        "D_E04": 4000.0,
        "D_E01": 3000.0,
        "D_E05": 3000.0,
        "D_E03": 2500.0,
        "D_E08": 2500.0,
        "D_E09": 2000.0,
        "D_E06": 1500.0,
        "D_E10": 1500.0,
    }
)

if rem_days > 60:
    nm.analytics.set_targeted_dev_spend({
        "D_E04": 5000.0,
        "D_E06": 4500.0,
        "D_E01": 4500.0,
        "D_E05": 4500.0,
        "D_E03": 4500.0,
        "D_E07": 3500.0,
        "D_E10": 3500.0,
        "D_S09": 4000.0,
        "D_S02": 3500.0,
        "D_S01": 3000.0,
        "E2": 3500.0,
        "E3": 3500.0,
        "S2": 1500.0,
        "S3": 1000.0,
    })
else:
    nm.analytics.set_targeted_dev_spend({})

# 6. Targeted Ads ($50k/d on high-WTP fresh segments when cap_util < 0.82)
if cap_util < 0.82 and rem_days > 35:
    ad_spend = {
        "referral_program": {
            "D_S07": 8000.0,
            "D_S05": 5000.0,
            "D_S01": 4000.0,
            "D_S02": 4000.0,
            "D_S06": 2000.0,
        },
        "search_ads": {
            "D_S09": 8000.0,
        },
        "social_media": {
            "D_S04": 6000.0,
            "D_S02": 5000.0,
        },
        "content_marketing": {
            "D_S04": 4000.0,
            "D_S10": 4000.0,
        },
        "linkedin": {},
    }
else:
    ad_spend = {}
r_ads = nm.marketing.set_targeted_ad_spend(ad_spend)
print("Ad spend set to:", r_ads.get("total_per_day"))

# 7. Rotating authentic engineering social media post
posts_pool = [
    "Shipped zero-overhead context caching across all NovaMind endpoints: P95 latency down to 112ms, 99.996% uptime, and instant 24/7 dedicated SRE triage for regulated workloads.",
    "Published quarterly security & accuracy audit: SOC 2 Type II, HIPAA, FERPA, FedRAMP & NERC verified with deterministic structured reasoning reducing downstream QA costs by 62%.",
    "NovaMind multi-step agentic workflows now process 165M+ daily production requests with deterministic tool validation, audit logging, and predictable ROI-backed seat tiers.",
    "Upgraded dedicated enterprise support routing: <10-minute direct engineer response SLA, automated schema migration tools, and isolated regional compliance enclaves.",
]
post_text = posts_pool[(day // 7) % len(posts_pool)]
r_post = nm.marketing.post_social_media(content=post_text)
print("Posted social update:", r_post.get("agent_post_id"))

